function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6;
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

function lineTotal(line) {
  return line.qty * line.unitPrice;
}

function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const lineDiscountAmount = roundCents(total * discountPercent / 100);
  let totalDiscount = lineDiscountAmount;
  if (line.qty >= 10) {
    const remainingAfterLineDiscount = total - lineDiscountAmount;
    const bulkDiscountAmount = roundCents(remainingAfterLineDiscount * 2.5 / 100);
    totalDiscount = lineDiscountAmount + bulkDiscountAmount;
  }
  return Math.max(0, totalDiscount);
}

function lineVAT(line) {
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  const vat = roundCents(amountAfterDiscount * line.vatRate / 100);
  return Math.max(0, vat);
}

// Test 1: invoiceTotals calculates subtotal as sum of line totals
console.log('Test 1: invoiceTotals calculates subtotal as sum of line totals');
const lines1 = [
