  { sku: 'STICKER', qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 21 }
];
let subtotal = 0, discount = 0, vat = 0;
for (let line of lines1) {
  subtotal += lineTotal(line);
  discount += lineDiscount(line);
  vat += lineVAT(line);
}
console.log(`subtotal: ${subtotal}, discount: ${discount}, vat: ${vat}, total: ${subtotal - discount + vat}`);

